import java.io.*;
import java.util.*;

public class C {

	BufferedReader reader;
	PrintWriter writer;
	StringTokenizer tokens;
	boolean eofFlag;

	void execute() throws IOException {
		nextInt();
		String s = nextToken();
		writer.println(fast(s));
	}

	static final String BAD_CHARS = "VK";

	String convert(String s) {
		StringBuilder sb = new StringBuilder();
		for (char c : s.toCharArray()) {
			if (BAD_CHARS.indexOf(c) >= 0) {
				sb.append(c);
			} else {
				sb.append('A');
			}
		}
		return sb.toString();
	}

	int slowMethod(String s) {
		s = convert(s);
		Map<String, Integer> visited = new HashMap<>();
		ArrayDeque<String> queue = new ArrayDeque<>();
		queue.add(s);
		visited.put(s, 0);

		while (true) {
			String current = queue.poll();
			int dist = visited.get(current);
			if (current.indexOf(BAD_CHARS) == -1) {
				return dist;
			}
			for (int i = 0; i < current.length() - 1; i++) {
				String swapped = swapChars(current, i, i + 1);
				if (swapped != null && !visited.containsKey(swapped)) {
					visited.put(swapped, dist + 1);
					queue.add(swapped);
				}
			}
		}
	}

	String swapChars(String s, int i, int j) {
		if (s.charAt(i) == s.charAt(j)) return null;
		char[] arr = s.toCharArray();
		char tmp = arr[i];
		arr[i] = arr[j];
		arr[j] = tmp;
		return new String(arr);
	}

	static final String TARGET = "VKA";

	int fast(String s) {
		s = convert(s);
		int n = s.length();
		int[] a = new int[n];
		int[][] pos = new int[3][n];
		int[] sz = new int[3];

		int[][][] cntHere = new int[3][n][3];

		int[][] pref = new int[n + 1][];
		pref[0] = new int[] { 0, 0, 0 };

		for (int i = 0; i < n; i++) {
			a[i] = TARGET.indexOf(s.charAt(i));
			int c = a[i];
			cntHere[c][sz[c]] = pref[i].clone();
			pos[c][sz[c]] = i;
			sz[c]++;
			pref[i + 1] = pref[i].clone();
			pref[i + 1][c]++;
		}

		int[][][][] dp = new int[2][sz[0] + 1][sz[1] + 1][sz[2] + 1];

		for (int i = 0; i < 2; i++) {
			for (int j0 = 0; j0 <= sz[0]; j0++) {
				for (int j1 = 0; j1 <= sz[1]; j1++) {
					Arrays.fill(dp[i][j0][j1], INF);
				}
			}
		}

		int answer = INF;
		dp[0][0][0][0] = 0;

		for (int j0 = 0; j0 <= sz[0]; j0++) {
			for (int j1 = 0; j1 <= sz[1]; j1++) {
				for (int j2 = 0; j2 <= sz[2]; j2++) {
					for (int last = 0; last < 2; last++) {
						int totalIdx = j0 + j1 + j2;
						int current = dp[last][j0][j1][j2];
						if (current == INF) continue;
						if (totalIdx == n) {
							answer = Math.min(answer, current);
							continue;
						}
						if (j0 < sz[0]) {
							int cost = Math.max(j1 - cntHere[0][j0][1], 0)
									+ Math.max(j2 - cntHere[0][j0][2], 0);
							dp[1][j0 + 1][j1][j2] = Math.min(dp[1][j0 + 1][j1][j2], current + cost);
						}
						if (j1 < sz[1] && last == 0) {
							int cost = Math.max(j0 - cntHere[1][j1][0], 0)
									+ Math.max(j2 - cntHere[1][j1][2], 0);
							dp[0][j0][j1 + 1][j2] = Math.min(dp[0][j0][j1 + 1][j2], current + cost);
						}
						if (j2 < sz[2]) {
							int cost = Math.max(j0 - cntHere[2][j2][0], 0)
									+ Math.max(j1 - cntHere[2][j2][1], 0);
							dp[0][j0][j1][j2 + 1] = Math.min(dp[0][j0][j1][j2 + 1], current + cost);
						}
					}
				}
			}
		}
		return answer;
	}

	static final int INF = 1_000_000;

	String generate() {
		Random rand = new Random(789);
		int n = 9;
		char[] buf = new char[n];
		for (int i = 0; i < n; i++) {
			buf[i] = TARGET.charAt(rand.nextInt(3));
		}
		return new String(buf);
	}

	void stressTest() {
		Random rand = new Random(789);
		for (int t = 0;; t++) {
			String s = generate();
			int fastRes = fast(s);
			int slowRes = slowMethod(s);
			if (fastRes != slowRes) {
				System.err.println("Discrepancy on: " + s);
				System.err.println("Fast: " + fastRes);
				System.err.println("Slow: " + slowRes);
				throw new AssertionError();
			}
			System.err.println("Iteration: " + t);
		}
	}

	C() throws IOException {
		reader = new BufferedReader(new InputStreamReader(System.in));
		writer = new PrintWriter(System.out);
		execute();
		// stressTest();
		writer.close();
	}

	public static void main(String[] args) throws IOException {
		new C();
	}

	String next() {
		while (tokens == null || !tokens.hasMoreTokens()) {
			try {
				tokens = new StringTokenizer(reader.readLine());
			} catch (Exception e) {
				eofFlag = true;
				return null;
			}
		}
		return tokens.nextToken();
	}

	String readLine() {
		try {
			return reader.readLine();
		} catch (IOException e) {
			eofFlag = true;
			return null;
		}
	}

	int getNextInt() throws IOException {
		return Integer.parseInt(next());
	}

	long getNextLong() throws IOException {
		return Long.parseLong(next());
	}

	double getNextDouble() throws IOException {
		return Double.parseDouble(next());
	}
}
